from array import array

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        INF = 10**9
        STATES = 79
        NONE = 78

        dp = [None] * (n + 1)

        base_row = array("i", [INF]) * STATES
        for c in range(26):
            base_row[c * 3 + 2] = 0
        dp[n] = base_row

        for i in range(n - 1, -1, -1):
            a = ord(caption[i]) - 97
            nxt = dp[i + 1]
            row = array("i", [INF]) * STATES

            best1 = best2 = INF
            best1_idx = -1

            switch_vals = [0] * 26
            for c in range(26):
                dist = abs(a - c)
                val = dist + nxt[c * 3]
                switch_vals[c] = val
                if val < best1:
                    best2 = best1
                    best1 = val
                    best1_idx = c
                elif val < best2:
                    best2 = val

            row[NONE] = best1

            for c in range(26):
                base = c * 3
                dist = abs(a - c)

                row[base] = dist + nxt[base + 1]
                row[base + 1] = dist + nxt[base + 2]

                continue_cost = dist + nxt[base + 2]
                switch_cost = best1 if best1_idx != c else best2
                row[base + 2] = min(continue_cost, switch_cost)

            dp[i] = row

        if dp[0][NONE] >= INF:
            return ""

        ans = []
        state = NONE

        for i in range(n):
            a = ord(caption[i]) - 97

            for c in range(26):
                if state == NONE:
                    next_state = c * 3
                else:
                    prev = state // 3
                    run_len = state % 3 + 1

                    if c == prev:
                        next_state = prev * 3 + min(2, run_len)
                    elif run_len == 3:
                        next_state = c * 3
                    else:
                        continue

                if abs(a - c) + dp[i + 1][next_state] == dp[i][state]:
                    ans.append(chr(c + 97))
                    state = next_state
                    break

        return "".join(ans)
